package com.tnr.cityguide.auth;
import com.tnr.cityguide.config.AppProperties;import com.tnr.cityguide.user.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import org.springframework.core.env.Environment;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class AuthService {
 private static final String DUMMY_HASH="$2a$12$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy";
 private final UserRepository users;private final RefreshTokenRepository refresh;private final PasswordResetTokenRepository resets;private final PasswordEncoder encoder;private final JwtService jwt;private final LoginAttemptService attempts;private final MailService mail;private final AppProperties props;private final Clock clock;private final Environment environment;private final SecureRandom random=new SecureRandom();
 public AuthService(UserRepository u,RefreshTokenRepository r,PasswordResetTokenRepository pr,PasswordEncoder e,JwtService j,LoginAttemptService a,MailService m,AppProperties p,Clock c,Environment env){users=u;refresh=r;resets=pr;encoder=e;jwt=j;attempts=a;mail=m;props=p;clock=c;environment=env;}
 @Transactional public AuthDtos.AuthResponse register(AuthDtos.RegisterRequest r){String email=normal(r.email());Map<String,String> errors=new LinkedHashMap<>();if(r.name()==null||r.name().trim().length()<2)errors.put("name","Please enter your full name.");if(!validEmail(email))errors.put("email","Enter a valid email address.");else if(users.existsByEmailIgnoreCase(email))errors.put("email","An account with this email already exists.");String pw=passwordMessage(r.password());if(pw!=null)errors.put("password",pw);if(!Objects.equals(r.password(),r.confirmPassword()))errors.put("confirm","Passwords do not match.");if(!errors.isEmpty())throw new FieldValidationException(errors);User u=new User();u.setName(r.name().trim());u.setEmail(email);u.setPasswordHash(encoder.encode(r.password()));u.setRole(Role.USER);users.save(u);return issue(u);}
 @Transactional public AuthDtos.AuthResponse login(AuthDtos.LoginRequest r){if(r==null||!validEmail(normal(r.email()))||r.password()==null||r.password().isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter your email and password");String email=normal(r.email());if(attempts.isLocked(email))throw new LoginLockedException(attempts.secondsLeft(email));User user=users.findByEmailIgnoreCase(email).orElse(null);if(!encoder.matches(r.password(),user==null?DUMMY_HASH:user.getPasswordHash())){attempts.failed(email);if(attempts.isLocked(email))throw new LoginLockedException(attempts.secondsLeft(email));throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Incorrect email or password.");}attempts.success(email);return issue(user);}
 @Transactional(noRollbackFor=ResponseStatusException.class) public AuthDtos.AuthResponse refresh(String raw){String hash=sha(raw);RefreshToken t=refresh.findByTokenHash(hash).orElseThrow(this::expired);if(t.isRevoked()){refresh.revokeAll(t.getUser().getId());throw expired();}if(!t.getExpiresAt().isAfter(clock.instant())){t.setRevoked(true);throw expired();}User user=users.findById(t.getUser().getId()).orElseThrow(this::expired);t.setRevoked(true);return issue(user);}
 @Transactional public void logout(String raw){if(raw!=null)refresh.findByTokenHash(sha(raw)).ifPresent(t->t.setRevoked(true));}
 @Transactional public Map<String,Object> forgot(String email){String normalized=normal(email);if(!validEmail(normalized))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter a valid email address.");String[] codeOut={null};users.findByEmailIgnoreCase(normalized).ifPresent(user->{resets.findByUserIdAndUsedAtIsNull(user.getId()).forEach(t->t.setUsedAt(clock.instant()));String code=String.format("%06d",100000+random.nextInt(900000));codeOut[0]=code;PasswordResetToken t=new PasswordResetToken();t.setUser(user);t.setTokenHash(sha(code));t.setExpiresAt(clock.instant().plus(Duration.ofMinutes(props.reset().codeTtlMinutes())));resets.save(t);mail.sendPasswordResetCode(normalized,code);});Map<String,Object> out=new LinkedHashMap<>();out.put("message","If an account exists, a code has been sent.");if(props.dev().returnResetCode()&&Arrays.asList(environment.getActiveProfiles()).contains("local")&&codeOut[0]!=null)out.put("devCode",codeOut[0]);return out;}
 @Transactional(noRollbackFor=ResponseStatusException.class) public void reset(AuthDtos.ResetRequest r){String email=normal(r.email());User u=users.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"This code has expired. Request a new one."));PasswordResetToken t=resets.findByUserIdAndUsedAtIsNull(u.getId()).stream().max(Comparator.comparing(PasswordResetToken::getExpiresAt)).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"This code has expired. Request a new one."));if(!t.getExpiresAt().isAfter(clock.instant())||t.getAttempts()>=props.reset().maxAttempts())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"This code has expired. Request a new one.");if(!MessageDigest.isEqual(t.getTokenHash().getBytes(StandardCharsets.UTF_8),sha(r.code()).getBytes(StandardCharsets.UTF_8))){t.setAttempts(t.getAttempts()+1);if(t.getAttempts()>=props.reset().maxAttempts())t.setUsedAt(clock.instant());throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The code is incorrect.");}String problem=passwordMessage(r.password());if(problem!=null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,problem);if(!Objects.equals(r.password(),r.confirmPassword()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Passwords do not match.");t.setUsedAt(clock.instant());u.setPasswordHash(encoder.encode(r.password()));refresh.revokeAll(u.getId());}
 @Transactional public AuthDtos.AuthResponse issueFresh(UUID id){return issue(users.findById(id).orElseThrow(this::expired));}
 private AuthDtos.AuthResponse issue(User u){String raw=newToken();RefreshToken t=new RefreshToken();t.setUser(u);t.setTokenHash(sha(raw));t.setExpiresAt(clock.instant().plus(props.jwt().refreshTtl()));refresh.save(t);return new AuthDtos.AuthResponse(jwt.accessToken(u),raw,"Bearer",jwt.expiresIn(),new AuthDtos.UserDto(u.getId(),u.getName(),u.getEmail(),u.getPhone(),u.getAvatarUrl(),u.getRole().name(),new AuthDtos.Prefs(u.isNotifEvents(),u.isNotifReviews(),u.isNotifNews())));}
 private String newToken(){byte[] b=new byte[32];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}private String normal(String v){return v==null?"":v.trim().toLowerCase(Locale.ROOT);}private boolean validEmail(String v){return v.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");}
 private String passwordMessage(String p){if(p==null)p="";List<String> m=new ArrayList<>();if(p.length()<8)m.add("at least 8 characters");if(!p.matches(".*[A-Z].*"))m.add("an uppercase letter");if(!p.matches(".*[a-z].*"))m.add("a lowercase letter");if(!p.matches(".*\\d.*"))m.add("a number");return m.isEmpty()?null:"Password needs "+String.join(", ",m)+".";}
 private String sha(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((v==null?"":v).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private ResponseStatusException expired(){return new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Session expired. Please log in again.");}
}
